from pathlib import Path
p=Path('.system-proof/t1/check-open-spec.rs');s=p.read_text();i=s.index('\\n}\\nfn main()');s=s[:i]+'''
proof fn frame_unique(before: Seq<u8>, a: Seq<u8>, c: Seq<u8>, p: Seq<u8>)
    requires write_frame(before, a, p), write_frame(before, c, p),
    ensures a == c,
{
    assert forall|i: int| 0 <= i < a.len() implies a[i] == c[i] by {
        if i < p.len() {
            assert(a.take(p.len() as int)[i] == a[i]);
            assert(c.take(p.len() as int)[i] == c[i]);
        }
    }
    assert(a =~= c);
}
proof fn encode_observation_unique(b: Seq<u8>, before: Seq<u8>, a: Seq<u8>, c: Seq<u8>, n: int, m: int)
    requires encode_post(b, before, a, n), encode_post(b, before, c, m),
    ensures n == m, a == c,
{
    frame_unique(before, a, c, encoding(b));
}
proof fn decode_observation_unique(b: Seq<u8>, before: Seq<u8>, a: Seq<u8>, c: Seq<u8>, n: int, m: int)
    requires decode_post(b, before, a, n), decode_post(b, before, c, m),
    ensures n == m, a == c,
{
    frame_unique(before, a, c, b);
}
'''+s[i:];p.write_text(s)
