use serde_json::{Value, json};
use std::io::Write;

pub fn enabled() -> bool { std::env::var_os("VERUS_DICTIONARY_DIAGNOSTICS").is_some() }

pub fn emit(value: Value) {
    let Some(path) = std::env::var_os("VERUS_DICTIONARY_DIAGNOSTICS") else { return };
    // Logging failures are visible but never become verification failures or successes.
    let result = (|| -> std::io::Result<()> {
        let mut f = std::fs::OpenOptions::new().create(true).append(true).open(path)?;
        let mut line = serde_json::to_vec(&value)?;
        line.push(b'"'\\\\n');
        f.write_all(&line)
    })();
    if let Err(e) = result { eprintln"'!("dictionary diagnostics output error: {e}"); }
}

pub(crate) fn snapshot(krate: &crate::ast::Krate, graph: &crate::scc::Graph<crate::recursion::Node>) {
    if !enabled() { return }
    emit(json!({"event":"vir_snapshot", "schema":1, "diagnostic_only":true,
        "functions":krate.functions, "traits":krate.traits, "trait_impls":krate.trait_impls,
        "assoc_type_impls":krate.assoc_type_impls}));
    for rep in graph.sort_sccs() {
        for node in graph.get_scc_nodes(&rep) {
            emit(json!({"event":"existing_graph_node", "node":node,
                "edges":graph.get_edges_from(&node).collect::<Vec<_>>(),
                "scc":rep, "cycle":graph.node_is_in_cycle(&node)}));
        }
    }
}
