use vstd::prelude::*;
verus"'! {
// Abstract instance identity: every coordinate participates in equality.
pub struct Instance {
    pub trait_id: int, pub self_ty: int, pub args: Seq<int>,
    pub binder: int, pub region: int, pub assoc_slot: int,
    pub decorated: int, pub undecorated: int,
}
pub struct Signature {
    pub receiver_ty: int, pub region: int, pub result_ty: int,
    pub mutable: bool, pub args: Seq<int>, pub binder: int,
}
pub struct Declaration {
    pub trait_id: int, pub assoc_slot: int, pub decorated: int,
    pub undecorated: int, pub spec_slot: int, pub default_body: int,
    pub has_default: bool,
}
pub struct Implementation {
    pub key: Instance, pub projection_key: Instance, pub config_ty: int,
    pub assignment_ty: int, pub spec_slot: int, pub body_spec_slot: int,
    pub base_sig: Signature, pub selected_sig: Signature,
    pub inherited: bool, pub body_id: int, pub override_id: int,
    // These functions describe arbitrary mathematical states and results.
    // They are not predicates granting Config/Engine availability.
    pub invariant: spec_fn(int) -> bool,
    pub base_req: spec_fn(int) -> bool, pub selected_req: spec_fn(int) -> bool,
    pub base_post: spec_fn(int, bool) -> bool,
    pub selected_post: spec_fn(int, bool) -> bool,
    pub spec_value: spec_fn(int) -> bool, pub body_value: spec_fn(int) -> bool,
    // Independent type evidence in the model, not Rust layout/coherence proof.
    pub universe: int, pub size_bytes: int, pub alignment: int,
    // IDs of independently supplied assignment/type/spec/body evidence.
    pub assignment_node: int, pub type_node: int, pub spec_node: int,
    pub body_node: int, pub config_node: int,
}
pub struct Graph { pub rank: Map<int, int>, pub edges: Set<(int,int)>, pub complete: int }

pub open spec fn ranked(g: Graph) -> bool {
    g.rank.dom().contains(g.complete)
    && forall|a:int,b:int| #[trigger] g.edges.contains((a,b)) ==>
        g.rank.dom().contains(a) && g.rank.dom().contains(b) && g.rank[b] < g.rank[a]
}
pub open spec fn before(g: Graph, n: int) -> bool {
    g.rank.dom().contains(n) && g.rank[n] < g.rank[g.complete]
}
pub open spec fn prefix_order(g: Graph, i: Implementation) -> bool {
    ranked(g) && before(g,i.config_node)
    && g.edges.contains((i.config_node,i.assignment_node))
    && g.edges.contains((i.config_node,i.type_node))
    && g.edges.contains((i.config_node,i.body_node))
    && g.edges.contains((i.body_node,i.spec_node))
}
pub open spec fn exact(d: Declaration, i: Implementation) -> bool {
    i.key.trait_id == d.trait_id && i.key.assoc_slot == d.assoc_slot
    && i.key.decorated == d.decorated && i.key.undecorated == d.undecorated
    && i.projection_key == i.key && i.assignment_ty == i.config_ty
    && i.spec_slot == d.spec_slot && i.body_spec_slot == d.spec_slot
    && i.base_sig == i.selected_sig
    && i.base_sig.receiver_ty == i.config_ty
    && i.base_sig.region == i.key.region && i.base_sig.binder == i.key.binder
    && i.base_sig.args == i.key.args && !i.base_sig.mutable
    && (if i.inherited { d.has_default && i.body_id == d.default_body }
        else { i.body_id == i.override_id })
}
pub open spec fn declaration_valid(d: Declaration) -> bool {
    // Separate namespaces must not collapse decorated and undecorated projections.
    d.decorated != d.undecorated
}
pub open spec fn obligations(i: Implementation) -> bool {
    i.universe == 0 && 0 <= i.size_bytes && 0 < i.alignment
    && (forall|x:int| (i.invariant)(x) && (i.base_req)(x) ==> (i.selected_req)(x))
    && (forall|x:int,r:bool| (i.invariant)(x) && (i.base_req)(x)
        && (i.selected_post)(x,r) ==> (i.base_post)(x,r))
    // Implementation checking is independent of the implication check.
    && (forall|x:int| (i.invariant)(x) && (i.selected_req)(x) ==>
        (i.selected_post)(x, (i.body_value)(x)))
    && (forall|x:int,r:bool| (i.invariant)(x) && (i.base_req)(x)
        && (i.base_post)(x,r) ==> r == (i.spec_value)(x))
}
pub open spec fn validated(d: Declaration,g: Graph,i: Implementation) -> bool {
    declaration_valid(d) && exact(d,i) && obligations(i) && prefix_order(g,i)
}
pub open spec fn available(d: Declaration,g: Graph,i: Implementation) -> bool {
    exact(d,i) && i.universe == 0 && 0 <= i.size_bytes && 0 < i.alignment
    && before(g,i.assignment_node) && before(g,i.type_node)
    && before(g,i.spec_node) && before(g,i.body_node) && before(g,i.config_node)
    && (forall|x:int| (i.invariant)(x) && (i.base_req)(x) ==>
        (i.base_post)(x,(i.body_value)(x)) && (i.body_value)(x) == (i.spec_value)(x))
}
pub proof fn earlier_dependency(g:Graph,a:int,b:int)
    requires ranked(g), before(g,a), g.edges.contains((a,b))
    ensures before(g,b)
{ assert(g.rank[b] < g.rank[a]); }

// Parametric: no finite enumeration of implementations or type arguments.
pub proof fn construct_prefix(d:Declaration,g:Graph,i:Implementation)
    requires validated(d,g,i)
    ensures available(d,g,i)
{
    earlier_dependency(g,i.config_node,i.assignment_node);
    earlier_dependency(g,i.config_node,i.type_node);
    earlier_dependency(g,i.config_node,i.body_node);
    earlier_dependency(g,i.body_node,i.spec_node);
    assert forall|x:int| (i.invariant)(x) && (i.base_req)(x) implies
        (i.base_post)(x,(i.body_value)(x)) && (i.body_value)(x) == (i.spec_value)(x) by {
        assert((i.selected_req)(x));
        assert((i.selected_post)(x,(i.body_value)(x)));
        assert((i.base_post)(x,(i.body_value)(x)));
    }
}
pub open spec fn registry_valid(d:Declaration,g:Graph,s:Seq<Implementation>) -> bool {
    forall|n:int| 0 <= n < s.len() ==> validated(d,g,#[trigger] s[n])
}
pub open spec fn coherent(s:Seq<Implementation>) -> bool {
    forall|a:int,b:int| 0 <= a < s.len() && 0 <= b < s.len()
        && #[trigger] s[a].key == #[trigger] s[b].key ==> a == b
}
pub proof fn empty_registry(d:Declaration,g:Graph)
    ensures registry_valid(d,g,Seq::empty()), coherent(Seq::<Implementation>::empty())
{}
// An arbitrary future extension has separate local validation obligations.
// We never assume every Rust implementation has such evidence.
pub proof fn extend(d:Declaration,g:Graph,s:Seq<Implementation>,i:Implementation)
    requires registry_valid(d,g,s), coherent(s), validated(d,g,i),
        forall|n:int| 0 <= n < s.len() ==> #[trigger] s[n].key != i.key
    ensures registry_valid(d,g,s.push(i)), coherent(s.push(i))
{
    assert forall|n:int| 0 <= n < s.push(i).len() implies validated(d,g,#[trigger] s.push(i)[n]) by {
        if n < s.len() { assert(s.push(i)[n] == s[n]); }
        else { assert(n == s.len()); assert(s.push(i)[n] == i); }
    }
    assert forall|a:int,b:int| 0 <= a < s.push(i).len() && 0 <= b < s.push(i).len()
        && #[trigger] s.push(i)[a].key == #[trigger] s.push(i)[b].key implies a == b by {
        if a < s.len() && b < s.len() { assert(s.push(i)[a] == s[a]); assert(s.push(i)[b] == s[b]); }
        else if a < s.len() { assert(s.push(i)[a] == s[a]); assert(b == s.len()); }
        else if b < s.len() { assert(s.push(i)[b] == s[b]); assert(a == s.len()); }
    }
}
pub proof fn selected_prefix(d:Declaration,g:Graph,s:Seq<Implementation>,n:int,key:Instance)
    requires registry_valid(d,g,s), coherent(s), 0 <= n < s.len(), s[n].key == key
    ensures available(d,g,s[n]), s[n].projection_key == key,
        forall|m:int| 0 <= m < s.len() && #[trigger] s[m].key == key ==> m == n
{ construct_prefix(d,g,s[n]); }

pub open spec fn path(g:Graph,p:Seq<int>) -> bool {
    0 < p.len() && forall|n:int| 0 <= n < p.len()-1 ==>
        #[trigger] g.edges.contains((p[n],p[n+1]))
}
pub proof fn path_before(g:Graph,p:Seq<int>)
    requires ranked(g), path(g,p), before(g,p[0])
    ensures before(g,p[p.len()-1]), p[p.len()-1] != g.complete
    decreases p.len()
{
    if p.len() > 1 {
        earlier_dependency(g,p[0],p[1]);
        let tail=p.drop_first();
        assert(path(g,tail)) by {
            assert forall|n:int| 0 <= n < tail.len()-1 implies
                #[trigger] g.edges.contains((tail[n],tail[n+1])) by {
                assert(g.edges.contains((p[n+1],p[n+2])));
            }
        }
        path_before(g,tail);
    }
}
// Two-cycle and direct completed dictionary are rejected independent of contract truth.
pub proof fn rejects_cycle(g:Graph,a:int,b:int)
    requires ranked(g), g.edges.contains((a,b))
    ensures !g.edges.contains((b,a))
{}
pub proof fn rejects_complete(g:Graph,a:int)
    requires ranked(g), before(g,a)
    ensures !g.edges.contains((a,g.complete))
{}
pub proof fn strengthening_is_not_body_evidence(x:int)
    ensures (false ==> true), !(false)
{}
}
fn main() {}
