verus"'! {
// Exclusive path representation: runtime fields of T62 Producer are unchanged.
pub struct Producer<'"'a> { first:&'a [u8], second:&'a [u8], flag:PCell<bool> }
impl<'a> Producer<'a> {
 pub fn new(first:&'a [u8],second:&'a [u8])->(r:(Self,Tracked<PointsTo<bool>>))
