 write_frame(old(encoded)@,final(encoded)@,encoding(raw@)),
)]
pub fn direct(raw:&[u8],invalid:&[u8],encoded:&mut [u8],decoded:&mut [u8])
 ->Result<usize,crate::DecodeSliceError>
{
 let engine=STANDARD;
